messages.content:
Tool response:
Tool: update_constituent_profile
Description: Update Constituent Profile
Parameters:
    {
      "type": "object",
      "properties": {
        "constituent_id": {
          "type": "string",
          "title": "Constituent Id",
          "description": ""
        },
        "engagement_score": {
          "type": "integer",
          "title": "Engagement Score"
        },
        "custom_attributes": {
          "anyOf": [
            {
              "items": {
                "properties": {
                  "name": {
                    "type": "string",
                    "title": "Name"
                  },
                  "value": {
                    "type": "string",
                    "title": "Value"
                  }
                },
                "type": "object",
                "required": [
                  "name",
                  "value"
                ],
                "title": "CustomAttributeRequest"
              },
              "type": "array"
            },
            {
              "type": "null"
            }
          ],
          "title": "Custom Attributes",
          "default": []
        },
        "note_text": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Note Text"
        }
      },
      "required": [
        "constituent_id",
        "engagement_score"
      ]
    }
